input.sparql:
SELECT ?point ?series ?pclass WHERE {
  ?point a brick:ThermalTemperatureSensor ;
         brick:hasParameter brick:Temperature ;
         brick:monitors ?zone .
  ?zone brick:hasTag "Basement" .
  ?point ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?series .
  ?point brick:hasProperty ?pclass .
}

SELECT ?z ?label ?zoneclass WHERE {
  ?zone a ?zoneclass .
  ?zone rdfs:label ?label .
  FILTER(LCASE(?label) LIKE "%basement%") .
}

SELECT ?zone ?label ?tag WHERE {
  ?zone a brick:HVAC_Zone .
  OPTIONAL { ?zone rdfs:label ?label . }
  OPTIONAL { ?zone brick:hasTag ?tag . }
}

SELECT ?sensor ?sclass ?seriesid ?extid WHERE {
  ?sensor a ?sclass ;
          brick:location http://buildgraph.org/BG_large_office_2004_0000#Zone_F1_Z01 .
  ?sensor ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?seriesid .
}

SELECT ?sensor ?sclass WHERE {
  ?sensor a brick:Zone_Air_Temperature_Sensor ;
          brick:location http://buildgraph.org/BG_large_office_2004_0000#Zone_F1_Z01 .
  OPTIONAL { ?sensor ref:hasExternalReference ?ext . }
  OPTIONAL { ?ext ref:hasTimeseriesId ?sid . } .
  BIND(?sensor AS ?sensor) .
}

PREFIX zone: <http://buildgraph.org/BG_large_office_2004_0000#>
SELECT ?sensor ?sclass ?seriesid WHERE {
  ?sensor a ?sclass ;
          brick:location zone:Zone_F1_Z01 .
  OPTIONAL { ?sensor ref:hasExternalReference ?ext . ?ext ref:hasTimeseriesId ?seriesid . }
}

PREFIX zone: <http://buildgraph.org/BG_large_office_2004_0000#>
SELECT ?pred ?obj WHERE {
  ?zone a brick:HVAC_Zone ; rdfs:label "Basement" .
  {?zone ?pred ?obj .} UNION {?obj ?pred2 ?zone .}
}

PREFIX zone: <http://buildgraph.org/BG_large_office_2004_0000#>
SELECT ?p ?pclass ?extid ?tsid WHERE {
  zone:Zone_F1_Z01.Zone_Air_Temperature_Sensor a ?pclass .
  ?p ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid .
}

PREFIX zone: <http://buildgraph.org/BG_large_office_2004_0000#>
SELECT ?p ?pclass ?ext ?tsid WHERE {
  ?p a brick:Zone_Air_Temperature_Sensor .
  FILTER(str(?p) LIKE "%Zone_F1_Z01%") .
  OPTIONAL { ?p ref:hasExternalReference ?ext . ?ext ref:hasTimeseriesId ?tsid . }
}
